import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long k = nextLong();
        int n = s.length(), answer = 0;
        // Try both global patterns 0101... and 1010...; a window is fine if its mismatches are <= k.
        for (int start = 0; start < 2; start++) {
            long bad = 0;
            int left = 0;
            for (int right = 0; right < n; right++) {
                if (s.charAt(right) - '0' != (right + start) % 2) bad++;
                while (bad > k) {
                    if (s.charAt(left) - '0' != (left + start) % 2) bad--;
                    left++;
                }
                answer = Math.max(answer, right - left + 1);
            }
        }
        System.out.println(answer);
    }
}

